"use client";

import * as React from "react";
import { cn } from "@/lib/utils";
import { fetchJson, normalizePercent, toNumber, type MarketOverviewResponse } from "./api";

interface MarketOverviewState {
  benchmark: string;
  currentIndex: number;
  mtdReturn: number;
  totalStocks: number;
  avgVolume: number;
  eligibleStocks: number;
  excludedInactiveCount: number;
  excludedStaleCount: number;
  excludedMissingAsOfCount: number;
  excludedMissingPrevCount: number;
  degradedMode: string | null;
  loading: boolean;
  error: string | null;
}

const EMPTY_MARKET_STATE: MarketOverviewState = {
  benchmark: "VN-Index",
  currentIndex: 0,
  mtdReturn: 0,
  totalStocks: 0,
  avgVolume: 0,
  eligibleStocks: 0,
  excludedInactiveCount: 0,
  excludedStaleCount: 0,
  excludedMissingAsOfCount: 0,
  excludedMissingPrevCount: 0,
  degradedMode: null,
  loading: true,
  error: null,
};

const IndexCard = React.memo(function IndexCard({
  benchmark,
  currentIndex,
  mtdReturn,
}: {
  benchmark: string;
  currentIndex: number;
  mtdReturn: number;
}) {
  const isPositive = mtdReturn >= 0;

  return (
    <div className="flex items-center justify-between border border-stone-200 bg-stone-50 p-3 dark:border-neutral-800 dark:bg-neutral-900/60">
      <div>
        <p className="font-semibold text-stone-900 dark:text-white">{benchmark}</p>
        <p className="text-xs text-stone-500 dark:text-neutral-400">Month-to-date return</p>
      </div>
      <div className="text-right">
        <p className="font-bold text-stone-900 dark:text-white">{currentIndex.toFixed(2)}</p>
        <p
          className={cn(
            "text-sm font-medium",
            isPositive ? "text-emerald-700 dark:text-emerald-400" : "text-rose-700 dark:text-rose-400"
          )}
        >
          {isPositive ? "+" : ""}
          {mtdReturn.toFixed(2)}%
        </p>
      </div>
    </div>
  );
});

const MarketStatsDisplay = React.memo(function MarketStatsDisplay({
  stats,
}: {
  stats: MarketOverviewState;
}) {
  const excludedTotal =
    stats.excludedInactiveCount
    + stats.excludedStaleCount
    + stats.excludedMissingAsOfCount
    + stats.excludedMissingPrevCount;
  const denominator = Math.max(1, stats.eligibleStocks + excludedTotal);

  const percentages = React.useMemo(
    () => ({
      eligible: (stats.eligibleStocks / denominator) * 100,
      inactive: (stats.excludedInactiveCount / denominator) * 100,
      staleOrMissing:
        ((stats.excludedStaleCount + stats.excludedMissingAsOfCount + stats.excludedMissingPrevCount) / denominator) * 100,
    }),
    [denominator, stats]
  );

  return (
    <div className="mt-auto border-t border-stone-200 pt-4 dark:border-neutral-800">
      <div className="mb-3 flex items-center gap-2">
        <div className="flex h-2 flex-1 overflow-hidden rounded-full bg-stone-200 dark:bg-neutral-800">
          <div className="bg-emerald-600" style={{ width: `${percentages.eligible}%` }} />
          <div className="bg-yellow-500" style={{ width: `${percentages.inactive}%` }} />
          <div className="bg-rose-500" style={{ width: `${percentages.staleOrMissing}%` }} />
        </div>
      </div>
      <div className="flex justify-between text-xs">
        <span className="text-emerald-700 dark:text-emerald-400">Eligible: {stats.eligibleStocks}</span>
        <span className="text-yellow-600 dark:text-yellow-400">Inactive: {stats.excludedInactiveCount}</span>
        <span className="text-rose-700 dark:text-rose-400">Stale/Missing: {excludedTotal - stats.excludedInactiveCount}</span>
      </div>

      <div className="mt-4 grid grid-cols-2 gap-4">
        <div className="border border-stone-200 bg-stone-50 p-2 text-center dark:border-neutral-800 dark:bg-neutral-900/60">
          <p className="text-xs text-stone-500 dark:text-neutral-400">Total Stocks</p>
          <p className="font-semibold text-stone-900 dark:text-white">{stats.totalStocks}</p>
        </div>
        <div className="border border-stone-200 bg-stone-50 p-2 text-center dark:border-neutral-800 dark:bg-neutral-900/60">
          <p className="text-xs text-stone-500 dark:text-neutral-400">Avg Volume</p>
          <p className="font-semibold text-stone-900 dark:text-white">{Math.round(stats.avgVolume).toLocaleString("vi-VN")}</p>
        </div>
      </div>
    </div>
  );
});

function MarketOverviewWidgetBase() {
  const [state, setState] = React.useState<MarketOverviewState>(EMPTY_MARKET_STATE);

  React.useEffect(() => {
    const controller = new AbortController();

    async function loadOverview() {
      setState((prev) => ({ ...prev, loading: true, error: null }));
      try {
        const payload = await fetchJson<MarketOverviewResponse>("/api/market-overview", controller.signal);
        if (controller.signal.aborted) return;
        setState({
          benchmark: String(payload.benchmark ?? "VN-Index"),
          currentIndex: toNumber(payload.currentIndex),
          mtdReturn: normalizePercent(toNumber(payload.mtdReturn)),
          totalStocks: Math.max(0, Math.trunc(toNumber(payload.totalStocks))),
          avgVolume: Math.max(0, toNumber(payload.avgVolume)),
          eligibleStocks: Math.max(0, Math.trunc(toNumber(payload.eligibleStocks))),
          excludedInactiveCount: Math.max(0, Math.trunc(toNumber(payload.excludedInactiveCount))),
          excludedStaleCount: Math.max(0, Math.trunc(toNumber(payload.excludedStaleCount))),
          excludedMissingAsOfCount: Math.max(0, Math.trunc(toNumber(payload.excludedMissingAsOfCount))),
          excludedMissingPrevCount: Math.max(0, Math.trunc(toNumber(payload.excludedMissingPrevCount))),
          degradedMode: typeof payload.degradedMode === "string" ? payload.degradedMode : null,
          loading: false,
          error: null,
        });
      } catch (error) {
        if (controller.signal.aborted) return;
        setState((prev) => ({
          ...prev,
          loading: false,
          error: error instanceof Error ? error.message : "Failed to load market overview",
        }));
      }
    }

    loadOverview();
    return () => controller.abort();
  }, []);

  return (
    <div className="flex h-full flex-col">
      <div className="mb-4 space-y-3">
        <IndexCard benchmark={state.benchmark} currentIndex={state.currentIndex} mtdReturn={state.mtdReturn} />
      </div>

      <MarketStatsDisplay stats={state} />
      <p className="mt-3 text-center text-xs text-stone-500 dark:text-neutral-500">
        {state.loading
          ? "Updating market overview..."
          : state.degradedMode === "low_memory"
            ? "Running in low-memory mode"
            : "Real-time snapshot from /api/market-overview"}
      </p>
      {state.error && (
        <p className="mt-2 text-center text-xs text-rose-700 dark:text-rose-300">{state.error}</p>
      )}
    </div>
  );
}

export const MarketOverviewWidget = React.memo(MarketOverviewWidgetBase);
